using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace SecureWorker
{
    public class EncryptedStorageConfig
    {
        public string VaultEndpoint { get; set; }
        public string EncryptionKeyId { get; set; }
        public string ServiceAccountDomain { get; set; }
        public bool RequireChannelBinding { get; set; } = true;
        public bool EnforceSignatureValidation { get; set; } = true;
    }

    public class NtlmAuthHandler : DelegatingHandler
    {
        private readonly EncryptedStorageConfig _config;
        private readonly ILogger _logger;

        public NtlmAuthHandler(EncryptedStorageConfig config, ILogger logger)
        {
            _config = config;
            _logger = logger;
            InnerHandler = CreateInnerHandler();
        }

        private HttpClientHandler CreateInnerHandler()
        {
            var handler = new HttpClientHandler
            {
                UseDefaultCredentials = false,
                PreAuthenticate = true
            };

            var cache = new CredentialCache();
            cache.Add(
                new Uri(_config.VaultEndpoint),
                "Negotiate",
                CredentialCache.DefaultNetworkCredentials);
            handler.Credentials = cache;

            // Channel binding token (CBT/EPA) enforcement
            // This prevents NTLM relay by binding auth to the TLS channel
            if (_config.RequireChannelBinding)
            {
                handler.ServerCertificateCustomValidationCallback = (msg, cert, chain, errors) =>
                {
                    // Validate certificate chain
                    if (errors != System.Net.Security.SslPolicyErrors.None)
                    {
                        _logger.LogWarning("Certificate validation failed: {Errors}", errors);
                        return false;
                    }
                    return true;
                };
            }

            return handler;
        }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            // Extended Protection for Authentication (EPA) check
            var epaEnabled = ValidateExtendedProtection(request);
            if (!epaEnabled && _config.RequireChannelBinding)
            {
                _logger.LogError("EPA validation failed - potential relay attack");
                throw new SecurityException("Channel binding required but not available");
            }

            return await base.SendAsync(request, cancellationToken);
        }

        private bool ValidateExtendedProtection(HttpRequestMessage request)
        {
            // Check if the target service supports EPA
            // In production, this validates the CBT against the TLS session
            var targetUri = request.RequestUri;
            if (targetUri.Scheme != "https")
                return false;

            // Service principal name validation for relay prevention
            var expectedSpn = $"HTTP/{targetUri.Host}";
            var configuredDomain = _config.ServiceAccountDomain;

            // Verify SPN matches expected domain - exact host validation
            return targetUri.Host.EndsWith(configuredDomain, StringComparison.OrdinalIgnoreCase)
                && targetUri.Host.Length > configuredDomain.Length;
        }
    }

    public class SecureVaultClient
    {
        private readonly HttpClient _httpClient;
        private readonly EncryptedStorageConfig _config;
        private readonly ILogger _logger;

        public SecureVaultClient(EncryptedStorageConfig config, ILogger logger)
        {
            _config = config;
            _logger = logger;
            var authHandler = new NtlmAuthHandler(config, logger);
            _httpClient = new HttpClient(authHandler);
        }

        public async Task<byte[]> RetrieveEncryptionKeyAsync(CancellationToken ct)
        {
            var endpoint = $"{_config.VaultEndpoint}/api/keys/{_config.EncryptionKeyId}";
            var response = await _httpClient.GetAsync(endpoint, ct);
            response.EnsureSuccessStatusCode();

            var keyData = await response.Content.ReadAsByteArrayAsync();
            return keyData;
        }
    }

    public class BackgroundJobWorker : BackgroundService
    {
        private readonly ILogger<BackgroundJobWorker> _logger;
        private readonly EncryptedStorageConfig _config;
        private readonly SecureVaultClient _vaultClient;

        public BackgroundJobWorker(ILogger<BackgroundJobWorker> logger, EncryptedStorageConfig config)
        {
            _logger = logger;
            _config = config;
            _vaultClient = new SecureVaultClient(config, logger);
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            while (!stoppingToken.IsCancellationRequested)
            {
                try
                {
                    await ProcessEncryptedWorkItems(stoppingToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing work items");
                }

                await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
            }
        }

        private async Task ProcessEncryptedWorkItems(CancellationToken ct)
        {
            var keyMaterial = await _vaultClient.RetrieveEncryptionKeyAsync(ct);

            using var aes = Aes.Create();
            aes.Key = keyMaterial;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            var workItems = await FetchPendingWorkItems(ct);
            foreach (var item in workItems)
            {
                var decrypted = DecryptWorkItem(aes, item);
                await ProcessItem(decrypted, ct);
            }

            CryptographicOperations.ZeroMemory(keyMaterial);
        }

        private byte[] DecryptWorkItem(Aes aes, byte[] encryptedItem)
        {
            if (encryptedItem == null)
                throw new ArgumentNullException(nameof(encryptedItem));

            // The payload must contain at least a full 16-byte IV plus one AES block
            // of ciphertext. Reject malformed/truncated input to avoid out-of-bounds
            // reads and undefined decryption behavior.
            const int ivLength = 16;
            if (encryptedItem.Length <= ivLength)
                throw new CryptographicException("Encrypted work item is too short to contain a valid IV and ciphertext.");

            // First 16 bytes are IV
            var iv = new byte[ivLength];
            Buffer.BlockCopy(encryptedItem, 0, iv, 0, ivLength);
            aes.IV = iv;

            using var decryptor = aes.CreateDecryptor();
            using var ms = new MemoryStream(encryptedItem, ivLength, encryptedItem.Length - ivLength);
            using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
            using var result = new MemoryStream();
            cs.CopyTo(result);
            return result.ToArray();
        }

        private Task<byte[][]> FetchPendingWorkItems(CancellationToken ct)
        {
            // Simulated - would fetch from encrypted queue
            return Task.FromResult(new byte[0][]);
        }

        private Task ProcessItem(byte[] data, CancellationToken ct)
        {
            _logger.LogInformation("Processed work item of {Length} bytes", data.Length);
            return Task.CompletedTask;
        }
    }

